import type { LayoutT } from "@glanceos/schema";

// Built-in "Start from a template" gallery: ~50 complete full-screen board
// designs composed from the standard blocks — so they add NOTHING to the screen
// runtime's byte budget. Every doc is validated against the Layout schema by
// starterTemplates.test.ts (run on every build), so the gallery can never ship a
// board the screen runtime can't render. Picking one creates an editable copy in
// Boards and opens the Studio.
export type StarterTemplate = {
  id: string;
  name: string;
  category: string;
  description: string;
  doc: LayoutT;
};

